transcript.command:
# Now trigger a crash to invoke the core handler
# The core handler runs in the HOST context and will have access to host /proc

# Create a simple C program that crashes (SIGSEGV)
cat > /tmp/crash.c << 'EOF'
#include <stdlib.h>
int main() {
    // Enable core dumps
    int *p = NULL;
    *p = 42;  // SIGSEGV
    return 0;
}
EOF

gcc -o /tmp/crash /tmp/crash.c
echo "Compiled crash program"

# Set core dump size to unlimited
ulimit -c unlimited

# Run the crash - this should trigger our core_pattern script on the HOST
/tmp/crash 2>/dev/null || echo "Crashed as expected"
sleep 2
echo "Done, checking results..."
